def transform(grid):
    """Keep the left/top pattern and recolor its marks to 2."""
    h, w = len(grid), len(grid[0])
    # Find a full nonzero separator line; the first panel contains the pattern.
    for c in range(1, w - 1):
        if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != 0:
            panel = [row[:c] for row in grid]
            return [[2 if value != 0 else 0 for value in row] for row in panel]
    for r in range(1, h - 1):
        if len(set(grid[r])) == 1 and grid[r][0] != 0:
            panel = grid[:r]
            return [[2 if value != 0 else 0 for value in row] for row in panel]
    raise ValueError("No full nonzero separator found")
